import React from 'react';

const projects = [
  {
    title: 'FEiOS AI Assistant',
    description: 'AI-powered development assistant that lives on your Linux machine',
    tech: ['Python', 'React', 'Ollama']
  },
  {
    title: 'E-Commerce Platform',
    description: 'Full-stack e-commerce with payment integration',
    tech: ['React', 'Node.js', 'MongoDB']
  },
  {
    title: 'Dev Portfolio',
    description: 'Modern developer portfolio with dark mode',
    tech: ['React', 'Tailwind', 'Framer Motion']
  }
];

const Projects = () => {
  return (
    <section id="projects" className="py-16 bg-gray-50 dark:bg-gray-800">
      <div className="container mx-auto px-4">
        <h2 className="text-3xl md:text-4xl font-bold text-center text-gray-800 dark:text-white mb-12">
          My Projects
        </h2>
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
          {projects.map((project, index) => (
            <div key={index} className="bg-white dark:bg-gray-900 rounded-lg shadow-lg p-6 hover:shadow-xl transition">
              <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
                {project.title}
              </h3>
              <p className="text-gray-600 dark:text-gray-300 mb-4">
                {project.description}
              </p>
              <div className="flex flex-wrap gap-2">
                {project.tech.map((tech, i) => (
                  <span key={i} className="px-3 py-1 bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200 text-sm rounded-full">
                    {tech}
                  </span>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Projects;
